for (var i = 0; i < tw.local.transactions.listLength; i++) {
	var sqlStatement = new tw.object.SQLStatement();
    tw.local.sqlStatements[i] = new tw.object.SQLStatement();
	tw.local.sqlStatements[i].sql = "SELECT ID FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE);";

	tw.local.sqlStatements[i].parameters = new tw.object.listOf.SQLParameter();
    tw.local.sqlStatements[i].parameters.insertIntoList(tw.local.sqlStatements[i].parameters.listLength, addSQLParameter(tw.local.transactions[i].referenceNumber));
    tw.local.sqlStatements[i].parameters.insertIntoList(tw.local.sqlStatements[i].parameters.listLength, addSQLParameter(tw.local.transactions[i].postingDate));
}

function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.transactionsIDs = [];

if (tw.local.sqlResults.listLength > 0) {
    for (var i = 0; i < tw.local.sqlResults.listLength; i++) {
        var result = tw.local.sqlResults[i];

        if (!!result.rows.listLength > 0 && result.rows[0].data) {
            tw.local.transactionsIDs.insertIntoList(tw.local.transactionsIDs.listLength, result.rows[0].data[0]);
        }
    }
}
